export const sketch:FirmwareSketch={"toolchain":"arduino-cli 1.5.1 · arduino:avr 1.8.8 · avr-gcc 7.3.0 · -fno-lto","lessonId":"tilt-alarm","variant":{"id":"default","sketch":"tilt-alarm-default","source":"// Lesson 18: Tilt alarm. MPU6050 on I2C (A4 = SDA, A5 = SCL, address 0x68), passive buzzer on D5,\n// 10-segment LED bar on D2,D3,D4,D6..D12 (segment 1 first). No libraries except Wire: the MPU6050 driver is ours.\nunsigned int alarmDeg = 45;     // tilt angle that sounds the buzzer\nunsigned int sampleMs = 50;     // ms between readings\n\n#include <Wire.h>\n#include <math.h>\n\nconst byte MPU = 0x68;\nconst byte BUZZER = 5;\nconst byte BAR[10] = {2, 3, 4, 6, 7, 8, 9, 10, 11, 12};\n\nbool mpuWrite(byte reg, byte value) {\n  Wire.beginTransmission(MPU);\n  Wire.write(reg);\n  Wire.write(value);\n  return Wire.endTransmission() == 0;\n}\n\n// Reads the three accelerometer axes (raw, 16384 per g at the default +-2 g range). Returns false if the chip does not answer.\nbool mpuAccel(int &ax, int &ay, int &az) {\n  Wire.beginTransmission(MPU);\n  Wire.write(0x3B);                       // ACCEL_XOUT_H\n  if (Wire.endTransmission(false) != 0) return false;\n  if (Wire.requestFrom((int)MPU, 6) != 6) return false;\n  ax = (Wire.read() << 8) | Wire.read();\n  ay = (Wire.read() << 8) | Wire.read();\n  az = (Wire.read() << 8) | Wire.read();\n  return true;\n}\n\nvoid showBar(byte n) {\n  for (byte i = 0; i < 10; i++) digitalWrite(BAR[i], i < n ? HIGH : LOW);\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  for (byte i = 0; i < 10; i++) pinMode(BAR[i], OUTPUT);\n  pinMode(BUZZER, OUTPUT);\n  Wire.begin();\n  mpuWrite(0x6B, 0x00);                   // PWR_MGMT_1 = 0: wake the chip from sleep\n  Serial.println(\"ready\");\n}\n\nvoid loop() {\n  int ax = 0, ay = 0, az = 0;\n  if (mpuAccel(ax, ay, az)) {\n    float x = ax / 16384.0, y = ay / 16384.0, z = az / 16384.0;\n    // tilt = angle between the board's up axis and gravity\n    float tilt = atan2(sqrt(x * x + y * y), z) * 57.29578;\n    if (tilt < 0) tilt = 0;\n    int deg = (int)(tilt + 0.5);\n    byte bars = (byte)(tilt * 10.0 / 90.0 + 0.5);\n    if (bars > 10) bars = 10;\n    showBar(bars);\n    if (deg >= (int)alarmDeg) {\n      tone(BUZZER, 1000);\n    } else {\n      noTone(BUZZER);\n    }\n    Serial.print(\"tilt \");\n    Serial.print(deg);\n    Serial.println(deg >= (int)alarmDeg ? \" ALARM\" : \" ok\");\n  } else {\n    showBar(0);\n    noTone(BUZZER);\n    Serial.println(\"no sensor\");\n  }\n  delay(sampleMs);\n}\n","template":"// Lesson 18: Tilt alarm. MPU6050 on I2C (A4 = SDA, A5 = SCL, address 0x68), passive buzzer on D5,\n// 10-segment LED bar on D2,D3,D4,D6..D12 (segment 1 first). No libraries except Wire: the MPU6050 driver is ours.\nunsigned int alarmDeg = {{alarmDeg}};     // tilt angle that sounds the buzzer\nunsigned int sampleMs = {{sampleMs}};     // ms between readings\n\n#include <Wire.h>\n#include <math.h>\n\nconst byte MPU = 0x68;\nconst byte BUZZER = 5;\nconst byte BAR[10] = {2, 3, 4, 6, 7, 8, 9, 10, 11, 12};\n\nbool mpuWrite(byte reg, byte value) {\n  Wire.beginTransmission(MPU);\n  Wire.write(reg);\n  Wire.write(value);\n  return Wire.endTransmission() == 0;\n}\n\n// Reads the three accelerometer axes (raw, 16384 per g at the default +-2 g range). Returns false if the chip does not answer.\nbool mpuAccel(int &ax, int &ay, int &az) {\n  Wire.beginTransmission(MPU);\n  Wire.write(0x3B);                       // ACCEL_XOUT_H\n  if (Wire.endTransmission(false) != 0) return false;\n  if (Wire.requestFrom((int)MPU, 6) != 6) return false;\n  ax = (Wire.read() << 8) | Wire.read();\n  ay = (Wire.read() << 8) | Wire.read();\n  az = (Wire.read() << 8) | Wire.read();\n  return true;\n}\n\nvoid showBar(byte n) {\n  for (byte i = 0; i < 10; i++) digitalWrite(BAR[i], i < n ? HIGH : LOW);\n}\n\nvoid setup() {\n  Serial.begin(9600);\n  for (byte i = 0; i < 10; i++) pinMode(BAR[i], OUTPUT);\n  pinMode(BUZZER, OUTPUT);\n  Wire.begin();\n  mpuWrite(0x6B, 0x00);                   // PWR_MGMT_1 = 0: wake the chip from sleep\n  Serial.println(\"ready\");\n}\n\nvoid loop() {\n  int ax = 0, ay = 0, az = 0;\n  if (mpuAccel(ax, ay, az)) {\n    float x = ax / 16384.0, y = ay / 16384.0, z = az / 16384.0;\n    // tilt = angle between the board's up axis and gravity\n    float tilt = atan2(sqrt(x * x + y * y), z) * 57.29578;\n    if (tilt < 0) tilt = 0;\n    int deg = (int)(tilt + 0.5);\n    byte bars = (byte)(tilt * 10.0 / 90.0 + 0.5);\n    if (bars > 10) bars = 10;\n    showBar(bars);\n    if (deg >= (int)alarmDeg) {\n      tone(BUZZER, 1000);\n    } else {\n      noTone(BUZZER);\n    }\n    Serial.print(\"tilt \");\n    Serial.print(deg);\n    Serial.println(deg >= (int)alarmDeg ? \" ALARM\" : \" ok\");\n  } else {\n    showBar(0);\n    noTone(BUZZER);\n    Serial.println(\"no sensor\");\n  }\n  delay(sampleMs);\n}\n","flashBase64":"","bytes":9476,"sha256":"3327316c4319bd404a57999d5bcf5cf1bfdedeedccdb5ec506bb3995fd568157","lines":[[160,166,32],[167,179,33],[180,184,34],[185,188,13],[189,193,14],[194,198,15],[199,203,16],[204,210,17],[211,214,18],[215,216,36],[228,235,38],[236,239,39],[240,243,40],[244,247,41],[248,251,42],[252,253,43],[254,255,42],[256,265,21],[266,270,22],[276,283,24],[284,291,30],[292,301,25],[302,316,26],[317,331,27],[332,347,28],[348,364,45],[365,370,46],[371,383,47],[384,415,48],[416,439,50],[440,455,48],[456,467,50],[468,477,51],[478,489,52],[490,512,53],[513,517,55],[518,525,56],[526,533,57],[534,539,61],[540,546,62],[547,557,63],[558,561,67],[562,569,69],[570,588,70],[589,592,59],[593,595,65],[596,598,66],[599,601,67]],"params":[{"name":"alarmDeg","ctype":"uint16","defaultValue":45,"min":15,"max":80,"step":5,"offset":9390},{"name":"sampleMs","ctype":"uint16","defaultValue":50,"min":20,"max":500,"step":10,"offset":9388}]}};
